package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_appendFixedWidthPadLeft_TriageGen1Test {

    @Test
    public void testAppendFixedWidthPadLeft_WidthGreaterThanZero_PaddingNeeded() {
        StrBuilder sb = new StrBuilder();
        // obj="abc" (len 3), width=5, padChar='0' -> "00abc"
        sb.appendFixedWidthPadLeft("abc", 5, '0');
        assertEquals("00abc", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthGreaterThanZero_NoPaddingNeeded() {
        StrBuilder sb = new StrBuilder();
        // obj="abcdef" (len 6), width=5 -> should take part of string based on logic:
        // strLen (6) >= width (5) -> str.getChars(6/5, 6, buffer, 0) -> str.getChars(1, 6, buffer, 0)
        // Note: The provided implementation logic for strLen >= width is: str.getChars(strLen / width, strLen, buffer, size);
        // If str="abcdef", width=5, strLen=6. strLen/width = 1. getChars(1, 6, buffer, 0) -> "bcdef"
        sb.appendFixedWidthPadLeft("abcdef", 5, '0');
        assertEquals("bcdef", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthEqualsLength() {
        StrBuilder sb = new StrBuilder();
        // obj="abc" (len 3), width=3 -> strLen/width = 1. getChars(1, 3, buffer, 0) -> "bc"
        // Wait, looking at the provided code logic: str.getChars(strLen / width, strLen, buffer, size);
        // If strLen=3, width=3, strLen/width=1. Result is chars from index 1 to 3.
        sb.appendFixedWidthPadLeft("abc", 3, '0');
        assertEquals("bc", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthIsZero() {
        StrBuilder sb = new StrBuilder("initial");
        // if (width > 0) is false. Nothing should happen.
        sb.appendFixedWidthPadLeft("abc", 0, '0');
        assertEquals("initial", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthIsNegative() {
        StrBuilder sb = new StrBuilder("initial");
        sb.appendFixedWidthPadLeft("abc", -1, '0');
        assertEquals("initial", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_NullObjectWithDefaultNullText() {
        StrBuilder sb = new StrBuilder();
        // obj is null, uses getNullText(). Default is "null"
        // "null" (len 4), width=6, padChar=' ' -> "  null"
        sb.appendFixedWidthPadLeft(null, 6, ' ');
        assertEquals("  null", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_CustomNullText() {
        StrBuilder sb = new StrBuilder();
        sb.setNullText("N/A");
        // "N/A" (len 3), width=5, padChar='-' -> "--N/A"
        sb.appendFixedWidthPadLeft(null, 5, '-');
        assertEquals("--N/A", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_ObjectToStringReturnsNull() {
        // To trigger: String str = (obj == null ? getNullText() : obj.toString()); if (str == null) { str = ""; }
        // We need an object whose toString() returns null.
        Object nullToStringObj = new Object() {
            @Override
            public String toString() {
                return null;
            }
        };
        StrBuilder sb = new StrBuilder();
        // str becomes "", width=3, padChar='x' -> "xxx"
        sb.appendFixedWidthPadLeft(nullToStringObj, 3, 'x');
        assertEquals("xxx", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_IntegerObject() {
        StrBuilder sb = new StrBuilder();
        // obj=123 (len 3), width=5, padChar='0' -> "00123"
        sb.appendFixedWidthPadLeft(123, 5, '0');
        assertEquals("00123", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_LargeWidth() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadLeft("a", 10, 'z');
        assertEquals("zzzzzzzzza", sb.toString());
    }
}
